// Decides whether to tell the owner. The rules are in the backend
// (backend/services/syncHealth.js); this only avoids repeating itself:
// a new set of problems is sent at once, the same set again after 6 h,
// and one 'cleared' message when they are gone. A switched-off factory PC
// (no recent heartbeat) is normal and changes nothing here.
const res = $input.first().json;
const state = $getWorkflowStaticData('global');
const REPEAT_MS = 6 * 3600 * 1000;
const now = Date.now();

let alerts;
if (res.statusCode === 200 && res.body && Array.isArray(res.body.alerts)) {
  if (!res.body.heartbeat_recent && res.body.alerts.length === 0) return [];
  alerts = res.body.alerts;
} else {
  const why = res.statusCode ? `it replied ${res.statusCode}` : (res.error && (res.error.message || res.error)) || 'no reply';
  alerts = [{ key: 'health_unreachable', message: `The online server's health check failed (${why})` }];
}

const key = alerts.map((a) => a.key).sort().join(',');
const out = [];
if (key) {
  if (key !== state.lastKey || now - (state.lastSentAt || 0) > REPEAT_MS) {
    out.push({ json: { message: `⚠️ FMS sync watchdog\n${alerts.map((a) => `• ${a.message}`).join('\n')}` } });
    state.lastSentAt = now;
  }
} else if (state.lastKey) {
  out.push({ json: { message: '✅ FMS sync watchdog: the earlier problem has cleared.' } });
}
state.lastKey = key;
return out;
